import React from "react";

function RoutePlanner({ tourist }) {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "linear-gradient(135deg, #FFEBCD, #FFD580)",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        flexDirection: "column",
        fontFamily: "Poppins, sans-serif",
      }}
    >
      <h1 style={{ color: "#8B0000", marginBottom: "20px" }}>
        🗺️ Welcome, {tourist?.name || "Tourist"}!
      </h1>
      <h2 style={{ color: "#333" }}>This is your Route Planner Page</h2>
      <p style={{ marginTop: "10px", fontSize: "16px", color: "#555" }}>
        Soon you’ll be able to explore the safest and most scenic routes
        across Varanasi, customized just for you.
      </p>
    </div>
  );
}

export default RoutePlanner;
